<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/src/bootstrap.php';$pdo=Database::connection();$driver=(string)config('database.driver','sqlite');$pdo->exec((string)file_get_contents(__DIR__.($driver==='mysql'?'/schema.mysql.sql':'/schema.sql')));
$email=mb_strtolower(getenv('DEMO_ADMIN_EMAIL')?:'admin@example.com');$password=getenv('DEMO_ADMIN_PASSWORD')?:'ChangeMe123!';$s=$pdo->prepare('SELECT COUNT(*) FROM users WHERE email=:email');$s->execute(['email'=>$email]);if(!(int)$s->fetchColumn()){$s=$pdo->prepare('INSERT INTO users(name,email,password_hash,created_at) VALUES(:name,:email,:hash,CURRENT_TIMESTAMP)');$s->execute(['name'=>getenv('DEMO_ADMIN_NAME')?:'Demo Administrator','email'=>$email,'hash'=>password_hash($password,PASSWORD_DEFAULT)]);}
if(!(int)$pdo->query('SELECT COUNT(*) FROM customers')->fetchColumn()){$s=$pdo->prepare('INSERT INTO customers(name,email,phone,company,created_at,updated_at) VALUES(:name,:email,:phone,:company,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)');foreach([['山田 太郎','taro.yamada@example.com','03-1234-5678','株式会社サンプル'],['佐藤 花子','hanako.sato@example.com','06-2345-6789','テスト商事'],['鈴木 一郎','ichiro.suzuki@example.com','052-345-6789','デモソリューションズ']] as $r)$s->execute(['name'=>$r[0],'email'=>$r[1],'phone'=>$r[2],'company'=>$r[3]]);}echo "Database initialized.\n";
